# -*- coding: utf-8 -*-
"""
ped13_cards_data.py
Bộ thẻ Anki Master cho PED-13: Suy hô hấp sơ sinh & Chỉ định Surfactant.
Basic-first (tier 1 khung → tier 2 chi tiết) + thẻ ⚡ thuật toán + cloze phụ giữ lịch sử ôn (legacy_note_id).
"""


def _c(t, col):
    return '<span style="color:' + col + '"><b>' + t + '</b></span>'


def R(t):  # đỏ: cờ đỏ / triệu chứng
    return _c(t, "#ff6b6b")


def Y(t):  # vàng: con số / tuổi / phủ định
    return _c(t, "#ffd43b")


def G(t):  # xanh lá: xử trí / thuốc / tiêu chuẩn vàng
    return _c(t, "#51cf66")


def D(t):  # xanh dương: tên bệnh / giải phẫu / phân loại
    return _c(t, "#74c0fc")


def _back(core, why):
    body = "<br>".join(str(i) + ") " + x for i, x in enumerate(core, 1))
    return "<b>🎯 Trả lời cốt lõi:</b><br>" + body + "<br><br><b>💡 Giải thích của AI:</b><br>" + why


def basic(cid, sec, cat, tier, front, core, why, src, algo=False):
    card = {
        "id": cid,
        "type": "basic",
        "section": sec,
        "category": cat,
        "tier": tier,
        "front": front,
        "back": _back(core, why),
        "extra": "📖 Nguồn: Bài PED-13, " + src,
        "tags": ["PED-13", sec],
    }
    if algo:
        card["badge"] = "⚡ THUẬT TOÁN QUYẾT ĐỊNH"
        card["badge_class"] = "badge-algo"
    else:
        card["badge"] = "🔬 EBM HIỆN ĐẠI & LÂM SÀNG"
        card["badge_class"] = "badge-ebm"
        card["track"] = "ebm"
    return card


def cloze(cid, sec, cat, text, src, legacy):
    return {
        "id": cid,
        "type": "cloze",
        "section": sec,
        "category": cat,
        "text": text,
        "extra": "📖 Nguồn: Bài PED-13, " + src,
        "legacy_note_id": legacy,
        "tags": ["PED-13", sec, "cloze"],
    }


